export type CapabilityPreparedActionInvalidatedByItem =
  | "record_revision"
  | "permission_change"
  | "user_change"
  | "application_event";

/**
 * CapabilityResponseObligation mirrors
 * urn:alixai:schema:application-package:capability:v1#/$defs/responseObligation.
 */
export interface CapabilityResponseObligation {
  /**
   * The path of the canonical value that must be stated, for example
   * reservation.pickup_date.
   */
  fact: FactPath;

  /**
   * success: in a response reporting a read result or a committed action. prepared: when
   * presenting a prepared action for confirmation. failure: in a failure response. always:
   * in every response.
   */
  when: CapabilityResponseObligationWhen;

  /**
   * What the fact is.
   */
  description: Text;
}

/**
 * CapabilityResponseObligationWhen mirrors
 * urn:alixai:schema:application-package:capability:v1#/$defs/responseObligation/properties/when.
 *
 * success: in a response reporting a read result or a committed action. prepared: when presenting
 * a prepared action for confirmation. failure: in a failure response. always: in every response.
 *
 * Only the values listed in the schema are valid.
 */
export type CapabilityResponseObligationWhen =
  | "success"
  | "prepared"
  | "failure"
  | "always";

/**
 * CapabilityScopeLevel mirrors
 * urn:alixai:schema:application-package:capability:v1#/properties/scope_level.
 *
 * The widest data scope one call can touch: principal (only the caller's own records), workspace
 * (records of the current workspace) or tenant (records across the workspaces of the current
 * tenant). Nothing wider exists: a capability can never cross tenants. The audit probes this
 * boundary with cross-scope tests.
 *
 * Only the values listed in the schema are valid.
 */
export type CapabilityScopeLevel =
  | "principal"
  | "workspace"
  | "tenant";

/**
 * CapabilityValidationRule mirrors
 * urn:alixai:schema:application-package:capability:v1#/$defs/validationRule.
 */
export interface CapabilityValidationRule {
  /**
   * Rule ID, unique in the capability. The documentation index covers it under the
   * validation_rule facet.
   */
  id: Slug;

  /**
   * The fields the rule checks. Empty for a rule over the whole request.
   */
  fields: FieldName[];

  /**
   * What the rule requires.
   */
  description: Text;

  /**
   * The platform error code returned when the rule fails. It must also appear in
   * failure_states.
   */
  error_code: ErrorCode;

  /**
   * Optional stable application-specific code for the same failure, for the host's own
   * support tooling.
   */
  application_code?: Slug;
}
